mapper.select:
SELECT g.id,
g.sku_id,
g.name,
g.short_name,
g.sale_price,
g.cost_price,
g.properties_value,
g.category,
g.vc_name,
g.item_type,
g.unit,
g.sku_type,
g.modified,
g.billing_name,
g.brand,
g.pic_big,
g.i_id,
g.market_price,
g.enabled,
g.is_fx,
g.actual_cost_price,
g.sale_cost_price,
g.level1_category,
g.level2_category,
g.is_count,
g.is_formal,
g.weight,
g.scancode,
g.is_group,
g.deleted,
g.create_time,
g.update_time,
g.creator,
g.updater,
g.auto_id
,if(i.qty,i.qty,0) as inventory
FROM fx_goods_archives g
LEFT JOIN fx.fx_inventory_data i ON i.sku_id = g.sku_id AND i.warehouse_code = #{reqVO.warehouseCode}


        AND g.sku_id = #{reqVO.skuId}


        AND g.name LIKE CONCAT('%', #{reqVO.name}, '%')


        AND g.short_name LIKE CONCAT('%', #{reqVO.shortName}, '%')


        AND g.sale_price = #{reqVO.salePrice}


        AND g.cost_price = #{reqVO.costPrice}


        AND g.properties_value = #{reqVO.propertiesValue}


        AND g.category = #{reqVO.category}


        AND g.vc_name LIKE CONCAT('%', #{reqVO.vcName}, '%')


        AND g.item_type = #{reqVO.itemType}


        AND g.unit = #{reqVO.unit}


        AND g.enabled = #{reqVO.enabled}


        AND g.is_fx = #{reqVO.isFx}


        AND g.actual_cost_price = #{reqVO.actualCostPrice}


        AND g.sale_cost_price = #{reqVO.saleCostPrice}


        AND g.level1_category = #{reqVO.level1Category}


        AND g.level2_category = #{reqVO.level2Category}


        AND g.is_count = #{reqVO.isCount}


        AND g.is_formal = #{reqVO.isFormal}


        AND g.weight = #{reqVO.weight}


        AND g.scancode = #{reqVO.scancode}


ORDER BY id DESC
